let reviewTab='Incoming cars',reviewDay='';
function reviewButton(){const raw=ReviewModel.summary(db),counts=db._view?.review,s=counts?{incoming:{length:counts.incoming},due:{length:counts.due},attention:counts.incoming+counts.due}:raw,merges=mergeReviewAvailable?(db._view?.carMerges?.total||0):0;return `<button type="button" id="review-button" class="btn header-review ${page==='Review'?'on':''}" data-action="open-review" aria-current="${page==='Review'?'page':'false'}" aria-label="Review local database: ${clubCount()} dealership changes, ${s.incoming.length} incoming cars, ${s.due.length} maintenance reminders due, ${db._view?.resultInbox?.total||0} unread race results, ${db._view?.historyImports?.total||0} historical imports${mergeReviewAvailable?', '+merges+' merge or late-history reviews':''}" title="${clubCount()} dealership changes · ${s.incoming.length} incoming cars · ${s.due.length} maintenance reminders due, ${db._view?.resultInbox?.total||0} unread race results, ${db._view?.historyImports?.total||0} historical imports${mergeReviewAvailable?', '+merges+' merge or late-history reviews':''}">${icon('inbox')} REVIEW${(s.attention+clubCount()+(db._view?.resultInbox?.total||0)+(db._view?.historyImports?.total||0)+merges)?'<span class="review-alert-dot" aria-hidden="true"></span>':''}</button>`;}
function captureReviewDraft(){
 const group=document.querySelector('[data-timing-collection]');if(group&&page==='Review'&&reviewTab==='Timing collection')return {timingCollection:group.dataset.timingCollection,keys:[...group.querySelectorAll('[data-collection-item]:checked')].map(e=>e.dataset.collectionKey)};
 const card=document.querySelector('[data-review-submission]');if(!card||page!=='Review'||reviewTab!=='Incoming cars')return null;
 return {database:card.dataset.reviewDatabase,id:card.dataset.reviewSubmission,carId:card.dataset.reviewCar,note:$('#review-note')?.value||'',fields:[...card.querySelectorAll('[data-review-field]')].map(e=>[e.dataset.reviewField,e.checked]),overrides:[...card.querySelectorAll('[data-stock-override]')].map(e=>[e.dataset.stockOverride,e.checked]),setups:$('#review-setups')?.checked};
}
function restoreReviewDraft(draft){
 if(draft?.timingCollection){const group=document.querySelector('[data-timing-collection]');if(group?.dataset.timingCollection===draft.timingCollection)group.querySelectorAll('[data-collection-item]:not(:disabled)').forEach(e=>e.checked=draft.keys.includes(e.dataset.collectionKey));return;}
 const card=document.querySelector('[data-review-submission]');if(!draft||!card||draft.database!==card.dataset.reviewDatabase||draft.id!==card.dataset.reviewSubmission||draft.carId!==card.dataset.reviewCar)return;
 $('#review-note').value=draft.note;for(const [key,checked] of draft.fields){const el=card.querySelector('[data-review-field="'+CSS.escape(key)+'"]');if(el)el.checked=checked;}for(const [key,checked] of draft.overrides){const el=card.querySelector('[data-stock-override="'+CSS.escape(key)+'"]');if(el)el.checked=checked;}if($('#review-setups'))$('#review-setups').checked=!!draft.setups;
}
function updateReviewIndicator(){const button=$('#review-button');if(!button||!db)return;const holder=document.createElement('div');holder.innerHTML=reviewButton();const next=holder.firstElementChild;button.innerHTML=next.innerHTML;for(const name of ['class','aria-label','aria-current','title'])button.setAttribute(name,next.getAttribute(name));}
function openReview(tab){const raw=ReviewModel.summary(db),counts=db._view?.review,s=counts?{incoming:{length:counts.incoming},due:{length:counts.due},jobs:{length:counts.jobs}}:raw,already=page==='Review';switchCollection('local');page='Review';if(!already)reviewHistory=false;reviewTab=tab||(db._view?.timingCollection?.total?'Timing collection':clubCount()?'Club changes':already?reviewTab:s.incoming.length?'Incoming cars':db._view?.historyImports?.total?'Historical imports':db._view?.resultInbox?.total?'Race results':s.due.length?'Maintenance':s.jobs.length?'Workshop jobs':'Incoming cars');render();}
function renderReviewHub(){
  if(!local())return empty('Review belongs to your local database','Open your local collection to review incoming cars, workshop jobs and maintenance.',btn('Open local Review','open-review','primary'));
  const s=ReviewModel.summary(db),tabs=[['Incoming cars','inbox',db._view?.review?.incoming??s.incoming.length],['Workshop jobs','tool',db._view?.review?.jobs??s.jobs.length],['Maintenance','calendar',db._view?.review?.maintenance??s.maintenance.length]];
  if(mergeReviewAvailable)tabs.push(['Car merges','car',db._view?.carMerges?.total??null]);
  if(db._view?.timingCollection)tabs.unshift(['Timing collection','database',db._view.timingCollection.total]);
  if(db._view?.historyImports)tabs.push(['Historical imports','history',db._view.historyImports.total]);
  if(db._view?.resultInbox)tabs.push(['Race results','timer',db._view.resultInbox.total]);
  if(db.club)tabs.unshift(['Club changes','share',clubCount()]);
  const head=heading('Review','Incoming cars, race results, planned work and maintenance for '+db.settings.name,reviewTab==='Incoming cars'?btn('Refresh inbox','refresh-inbox'):reviewTab==='Workshop jobs'?btn(icon('plus')+' New workshop job','new-job','primary'):'');
  const nav=`<div class="tabs review-tabs" aria-label="Review sections">${tabs.map(([name,symbol,count])=>`<button type="button" data-action="review-tab" data-id="${name}" class="${reviewTab===name?'active':''}" aria-pressed="${reviewTab===name}">${icon(symbol)}${name==='Club changes'?'Dealership changes':name} ${count===null?'':'<span class="badge">'+count+'</span>'}</button>`).join('')}</div>`;
  if(reviewTab==='Car merges'&&mergeReviewAvailable)return head+nav+renderMergeHub();
  if(reviewTab==='Timing collection')return head+nav+renderTimingCollection();
  if(reviewTab==='Historical imports')return head+nav+renderHistoricalImports();
  if(reviewTab==='Race results')return head+nav+renderResultInbox();
  if(reviewTab==='Club changes'&&db.club)return head+nav+renderClubReview();
  if(reviewTab==='Incoming cars')return head+nav+(clubState?.active?empty('Incoming cars are reviewed on the dealership computer',s.incoming.length+' car(s) await review. Open this collection on the dealership computer to approve or reject them.'):renderReview());
  if(reviewTab==='Workshop jobs')return head+nav+(s.jobs.length?jobCards(s.jobs):empty('No open workshop jobs','Create a job to plan maintenance or work towards a saved setup.',btn('New workshop job','new-job','primary')));
  const groups=[['Overdue',s.due.filter(e=>e.nextDue<s.day),'overdue'],['Due today',s.due.filter(e=>e.nextDue===s.day),'today'],['Upcoming',s.upcoming,'upcoming']];
  return head+nav+(s.maintenance.length?groups.filter(([,items])=>items.length).map(([title,items,tone])=>`<section class="review-maintenance-section"><div class="section-heading"><h2>${title} <span class="badge">${items.length}</span></h2></div><div class="review-maintenance-grid">${items.map(e=>{const c=db.cars.find(c=>c.id===e.carId),job=s.jobs.find(j=>j.carId===c.id);return `<article class="panel review-maintenance-card ${tone}"><div class="row">${uiTile('calendar',tone==='overdue'?'accent':'amber')}<div><h3>${esc(e.task||e.title)}</h3><p class="muted">${esc(c.name)}</p></div></div><p class="review-due">${title==='Upcoming'?'Due':title} · ${date(e.nextDue)}</p><div class="actions">${btn('Open car','open-car','small',c.id)}${job?btn('Resume job','open-job','small',job.id):btn('Plan workshop job','maintenance-job','small',e.id)}</div></article>`;}).join('')}</div></section>`).join(''):empty('No maintenance reminders','Record maintenance on a car and set its next due date to see it here.'));
}
async function reviewAction(action,id){
  if(await timingCollectionAction(action,id))return true;
  if(action==='review-select-safe'||action==='review-select-none'){document.querySelectorAll('[data-review-field]').forEach(e=>{e.checked=action==='review-select-safe'&&!e.hasAttribute('data-stock-override');});return true;}
  if(action==='open-review'){openReview();return true;}
  if(action==='review-tab'){if([...(mergeReviewAvailable?['Car merges']:[]),'Timing collection','Club changes','Incoming cars','Workshop jobs','Maintenance','Race results','Historical imports'].includes(id)){reviewTab=id;render();}return true;}
  if(action==='history-import-inspect'){await inspectHistoricalImport(id);return true;}
  if(action==='result-session'){const row=db._view?.resultInbox?.rows?.[Number(id)],context=db.id;if(row&&window.slotforge.historyView){await openSharedHistory(row.source,row.session,row.primaryCar||row.cars[0]);return true;}if(row){const result=await api('query','session',{sourceId:row.source,sessionId:row.session,carId:row.primaryCar||row.cars[0],offset:0,token:db._view.token});if(context!==db.id)return true;timingDetail={record:result.record,carId:row.primaryCar||row.cars[0],query:result};timingLapPage=0;showTimingSession();}return true;}
  if(action==='result-seen'){const row=db._view?.resultInbox?.rows?.[Number(id)];if(row){await api('query','result-seen',{databaseId:db.id,source:row.source,session:row.session,hash:row.hash});if(db._view.resultInbox.rows.length===1)viewOffset=Math.max(0,viewOffset-20);await loadView();}return true;}
  if(action==='result-open-car'){carId=id;section='Performance';page='Cars';render();return true;}
  if(action==='edit-job'){editWorkshopJob(id);return true;}
  if(action==='maintenance-job'){const e=ReviewModel.summary(db).maintenance.find(e=>e.id===id);if(e)newWorkshopJob(e.carId,e.task||e.title);return true;}
  return false;
}
function refreshReviewDate(){if(!db)return;const day=slotforgeDomain.today();if(day===reviewDay)return;reviewDay=day;if(local()&&db._view&&!$('#dialog').open){void loadView();return;}updateReviewIndicator();if(page==='Review'&&reviewTab==='Maintenance'&&!$('#dialog').open&&!actionBusy&&!modalSaving)render();}
function renderHistoricalImports(){
 if(clubState?.active)return empty('Review historical imports on the library computer','These decisions belong to the original library.');
 const rows=db._view?.historyImports?.rows||[];
 return '<p class="note info">Pending historical evidence does not contribute to laps, mileage, wins or records. '+(db._view?.historyImports?.approvalEnabled?'Inspect each item before approving or rejecting it. Approved evidence enters shared history without personal or track-record eligibility.':'New acceptance remains disabled while the Timing–Paddock approval workflow is qualified. You can inspect or reject evidence; retained approvals are labelled separately.')+'</p>'+ (rows.length?rows.map((r,i)=>panel(r.summary.name,`<div class="actions">${badge(r.status==='pending'?'Awaiting review':r.status,r.status==='pending'?'info':'')}<span class="muted">${esc(r.summary.track||'Unknown track')} · ${r.summary.startedAt?date(r.summary.startedAt):'Race date unknown'} · ${r.summary.laps} laps</span></div><p>${esc(r.summary.cars.slice(0,5).join(' · ')||'No linked physical cars')}${r.summary.cars.length>5?' · …':''}</p><p class="muted">From ${esc(r.batch.editor.name||r.batch.editor.application)} · Received ${date(r.receivedAt)}</p>${r.recoveryChanged?'<p class="note warning">Retained from an earlier recovery generation. Reconcile this evidence with Timing before resubmitting.</p>':''}<p>${esc(r.message)}</p>${r.decisionNote?'<p>Review note: '+esc(r.decisionNote)+'</p>':''}<div class="actions">${btn('Inspect evidence','history-import-inspect','',String(i))}</div>`)).join(''):empty('No historical imports','Older Timing sessions submitted for review will appear here. Normal race-result delivery continues unchanged.'));
}
async function inspectHistoricalImport(index){
 const info=db._view?.historyImports,row=info?.rows?.[Number(index)];if(!row)return;
 const payload={databaseId:db.id,recoveryId:info.recoveryId,id:row.id,requestHash:row.requestHash},result=await api('historyImport',{...payload,action:'inspect'});if(db.id!==payload.databaseId)return;
 showHistoricalEvidence(row,payload,result);
}
setInterval(refreshReviewDate,60000);
window.addEventListener('focus',refreshReviewDate);

function renderResultInbox(){if(db._view?.resultInbox?.error)return empty('Race-result notices unavailable',db._view.resultInbox.error);const rows=db._view?.resultInbox?.rows||[];return '<p class="note info">New or updated race results have been saved by Timing. Inspect them here; they already contribute to the car’s performance history. Corrections and withdrawals are made in Timing. Marking a notice as seen does not change its results.</p>'+ (rows.length?rows.map((r,i)=>panel(r.name||'Timing session',`<div class="actions">${badge(r.state==='withdrawn'?'Withdrawn':r.corrections?'Corrected':'Received',r.state==='withdrawn'?'':'info')}<span class="muted">Revision ${r.revision} · ${esc(connectionTime(r.received))}</span></div><p>${esc(r.track||'Track not included in withdrawal')}</p><div class="actions">${r.cars.slice(0,5).map(id=>{const c=db.cars.find(c=>c.id===id);return c?btn('View '+esc(c.name)+' results','result-open-car','',id):'<span class="muted">Car no longer in collection</span>';}).join('')}${r.cars.length>5?'<span class="muted">And '+(r.cars.length-5)+' more cars</span>':''}${btn('View session','result-session','',String(i))}${btn('Mark as seen','result-seen','',String(i))}</div>`)).join(''):empty('No unread race results','Timing results received while you are away will appear here after delivery.'));}
